shaders.source:
@group(0) @binding(0) var _sceneColorTex  : texture_2d<f32>;
@group(0) @binding(1) var _sceneColorSamp : sampler;
@group(0) @binding(2) var _sceneDepthTex  : texture_depth_2d;
@group(0) @binding(3) var _sceneDepthSamp : sampler;

struct UserUniforms {
  tint : vec3<f32>,
};
@group(0) @binding(4) var<uniform> u : UserUniforms;

struct PostOutput {
  @builtin(position) pos : vec4<f32>,
  @location(0) v_uv      : vec2<f32>,
};

const _postPositions = array<vec2<f32>, 3>(
  vec2<f32>(-1.0, -1.0),
  vec2<f32>( 3.0, -1.0),
  vec2<f32>(-1.0,  3.0),
);
const _postUVs = array<vec2<f32>, 3>(
  vec2<f32>(0.0, 1.0),
  vec2<f32>(2.0, 1.0),
  vec2<f32>(0.0, -1.0),
);

@vertex fn vertexMain(@builtin(vertex_index) vi : u32) -> PostOutput {
  var out : PostOutput;
  out.pos  = vec4<f32>(_postPositions[vi], 0.0, 1.0);
  out.v_uv = _postUVs[vi];
  return out;
}

struct PostInput {
  @location(0) v_uv : vec2<f32>,
};

@fragment fn fragmentMain(in : PostInput) -> @location(0) vec4<f32> {
  return vec4<f32>((textureSample(_sceneColorTex, _sceneColorSamp, in.v_uv).rgb * u.tint), 1.0);
}

shaders.vertex:
#version 300 es

out vec2 v_uv;

void main() {
  const vec2[3] positions = vec2[3](
    vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0)
  );
  const vec2[3] uvs = vec2[3](
    vec2(0.0, 1.0), vec2(2.0, 1.0), vec2(0.0, -1.0)
  );
  v_uv = uvs[gl_VertexID];
  gl_Position = vec4(positions[gl_VertexID], 0.0, 1.0);
}

shaders.fragment:
#version 300 es
precision highp float;
precision highp int;
in vec2 v_uv;

uniform sampler2D _sceneColor;
uniform sampler2D _sceneDepth;
uniform vec3 tint;
out vec4 fragColor;

void main() {
  fragColor = vec4((texture(_sceneColor, v_uv).rgb * tint), 1.0);
}
